using System;
using System.Drawing;
using System.IO;
using System.Linq;
using System.Threading.Tasks;
using System.Windows.Forms;
namespace OpenAntiLag {
 public sealed class DashboardPage:PlayerPage {
  readonly Label gameName,gameState,state,message,applied;readonly PictureBox icon;readonly ComboBox profiles;readonly Button primary;bool rendering;readonly Action<string> navigate;readonly Func<ProfileOptions> custom;readonly Func<string[]> machine;
  public DashboardPage(PlayerContext context,Action<string> navigate,Func<ProfileOptions> custom,Func<string[]> machine):base(context,"Всё готово к игре","Выберите игру, включите профиль и следите за реальными результатами."){this.navigate=navigate;this.custom=custom;this.machine=machine;Name="dashboardPage";var grid=new CardGrid();var game=new PlayerCard();game.Add(PlayerUi.Text("ВАША ИГРА",9,true,Theme.Muted));icon=new PictureBox {Height=64,Width=64,SizeMode=PictureBoxSizeMode.Zoom,Margin=new Padding(0,8,0,12)};game.Add(icon);gameName=PlayerUi.Text("Выберите игру",22,true);gameState=PlayerUi.Text("Добавьте игру из библиотеки или укажите EXE",10,false,Theme.Muted);game.Add(gameName);game.Add(gameState);profiles=PlayerUi.Choice("Стандартный","Соревновательный","Пользовательский");profiles.Name="playerProfile";game.Add(PlayerUi.Text("Профиль игры",10,true));game.Add(profiles);profiles.SelectedIndexChanged+=delegate{if(!rendering)context.SetProfile((PlayerProfile)profiles.SelectedIndex);};var library=PlayerUi.Button("Выбрать другую игру","chooseGame");library.Click+=delegate{navigate("Games");};game.Add(library);grid.Controls.Add(game);
   var optimization=new PlayerCard();optimization.Add(PlayerUi.Text("ПРОФИЛЬ WINDOWS",9,true,Theme.Muted));state=PlayerUi.Text("Проверяем настройки…",22,true);state.Name="playerStatus";message=PlayerUi.Text("",11,false,Theme.Muted);optimization.Add(state);optimization.Add(message);primary=PlayerUi.Button("Включить оптимизацию","playerPrimary",true);primary.Height=54;optimization.Add(primary);PlayerUi.Action(primary,Toggle,context);applied=PlayerUi.Text("",10,false,Theme.Muted);optimization.Add(applied);var recovery=PlayerUi.Button("Восстановление настроек","dashboardRecovery");recovery.Click+=delegate{navigate("Recovery");};optimization.Add(recovery);grid.Controls.Add(optimization);Add(grid);
   var quick=new PlayerCard();quick.Add(PlayerUi.Text("Под вашим контролем",16,true));quick.Add(PlayerUi.Text("Приложение сохраняет исходные значения перед изменениями. Видеокарта, ограничения интернета и шейдеры управляются отдельно.",10,false,Theme.Muted));var options=PlayerUi.Button("Посмотреть возможности");options.Click+=delegate{navigate("Optimization");};quick.Add(options);Add(quick);
  }
  async Task Toggle(){if(Context.Optimizer.Status.HasProfile){if(PlayerUi.Confirm(this,"Восстановить профиль Windows?","Вернуть сохранённые настройки профиля Windows? Для ранее применённых системных параметров может потребоваться UAC и перезагрузка.",Context.Preview)){Context.Session.SuppressCurrentRun(Context.Selected,Context.Processes);await Context.Optimizer.Restore();}return;}var profile=Context.Profile;var options=profile==PlayerProfile.Custom?custom():OptimizationOrchestrator.Options(profile);var selected=profile==PlayerProfile.Custom?machine():new string[0];string summary=OptimizationOrchestrator.Summary(options,selected)+(Context.Selected!=null&&Context.Selected.CanWatch&&profile!=PlayerProfile.Custom?"\n\nПрофиль привяжется к выбранной игре и восстановится после её завершения. Если игра ещё не запущена, приложение дождётся её запуска.":"\n\nЭтот профиль отключается вручную кнопкой восстановления.");if(PlayerUi.Confirm(this,"Перед включением",summary,Context.Preview)){if(Context.Selected!=null&&Context.Selected.CanWatch&&profile!=PlayerProfile.Custom)await Context.Session.ApplyManual(Context.Selected,Context.Processes);else await Context.Optimizer.Enable(profile,options,selected,Context.Selected==null?null:Context.Selected.Id);}}
  public override void RefreshState(){rendering=true;try{var selected=Context.Selected;gameName.Text=selected==null?"Выберите игру":selected.Name;gameState.Text=selected==null?"Откройте «Мои игры», чтобы выбрать или добавить игру.":!selected.CanWatch?"Укажите EXE для определения запуска":Context.Running?"Игра запущена":"Игра не запущена";if(icon.Tag as string!= (selected==null?null:selected.Id)){var previous=icon.Image;icon.Image=PlayerUi.GameIcon(selected);icon.Tag=selected==null?null:selected.Id;if(previous!=null)previous.Dispose();}profiles.SelectedIndex=(int)Context.Profile;profiles.Enabled=selected!=null&&!Context.Optimizer.Status.Busy;var status=Context.Optimizer.Status;state.Text=!status.HasProfile&&selected!=null&&selected.Automatic&&!Context.Running?"Ожидание запуска игры":status.Title;message.Text=(status.Stage==OptimizationStage.ErrorIncomplete?"Проверьте сохранённые изменения на экране восстановления. Причина ошибки — в разделе «Результаты».":status.Stage==OptimizationStage.ErrorRestored?"Применение не завершилось. Параметры не изменены или восстановлены. Причина — в разделе «Результаты».":status.Message)+(Context.Session.Faceit?"\nОбнаружен FACEIT. Совместимость не подтверждена; глобальные экспериментальные действия по умолчанию выключены.":"");primary.Text=status.HasProfile?(status.Stage==OptimizationStage.Enabled?"Отключить оптимизацию":"Восстановить оптимизацию"):"Включить оптимизацию";primary.Enabled=Context.Initialized&&!status.Busy;applied.Text=status.HasProfile?"Активный профиль: "+status.ProfileName:"Включение не запускает дополнительные модули автоматически.";}finally{rendering=false;}}
  protected override void Dispose(bool disposing){if(disposing&&icon.Image!=null)icon.Image.Dispose();base.Dispose(disposing);}
 }
 public sealed class GamesPage:PlayerPage {
  readonly TextBox search=new TextBox {Name="gameSearch",Width=340,BackColor=Theme.Surface,ForeColor=Theme.Text,BorderStyle=BorderStyle.FixedSingle};readonly CardGrid games=new CardGrid();string signature;
  public GamesPage(PlayerContext context):base(context,"Мои игры","Установленные игры из Steam и игры, добавленные вручную."){Name="gamesPage";var actions=new FlowLayoutPanel {AutoSize=true,WrapContents=true};search.TextChanged+=delegate{signature=null;RefreshState();};actions.Controls.Add(search);var scan=PlayerUi.Button("Найти установленные игры","scanInstalled");PlayerUi.Action(scan,async()=>{scan.Enabled=false;try{await context.Scan();}finally{scan.Enabled=true;}},context);actions.Controls.Add(scan);var add=PlayerUi.Button("Добавить EXE","addGame");PlayerUi.Action(add,()=>{using(var dialog=new OpenFileDialog {Title="Выберите файл запуска игры",Filter="Игра (*.exe)|*.exe"})if(dialog.ShowDialog()==DialogResult.OK)context.AddManual(dialog.FileName);return Task.FromResult(0);},context);actions.Controls.Add(add);Add(actions);Add(PlayerUi.Text("Поиск по названию",9,false,Theme.Muted));Add(games);}
  public override void RefreshState(){string key=Context.Preferences.SelectedGame+":"+Context.Running+":"+search.Text+":"+String.Join("|",Context.Preferences.Games.Select(g=>g.Id+g.Profile+g.Automatic+g.LastResult+g.Executable));if(signature==key)return;signature=key;foreach(Control card in games.Controls.Cast<Control>().ToArray()){games.Controls.Remove(card);card.Dispose();}var selected=Context.Preferences.Games.Where(g=>g.Name.IndexOf(search.Text,StringComparison.OrdinalIgnoreCase)>=0).Take(100).ToArray();if(selected.Length==0){var empty=new PlayerCard();empty.Add(PlayerUi.Text("Добавьте свою первую игру",18,true));empty.Add(PlayerUi.Text("Нажмите «Найти установленные игры» или выберите EXE вручную. Интернет и аккаунт не нужны.",10,false,Theme.Muted));games.Controls.Add(empty);return;}
   foreach(var game in selected){var item=game;var card=new PlayerCard();var image=GameDetectionService.Artwork(item);if(image!=null){var picture=new PictureBox {Image=image,Width=64,Height=64,SizeMode=PictureBoxSizeMode.Zoom};picture.Disposed+=delegate{image.Dispose();};card.Add(picture);}else card.Add(PlayerUi.Text(item.Name.StartsWith("Counter-Strike",StringComparison.OrdinalIgnoreCase)?"CS":"▶",22,true,Theme.Accent));card.Add(PlayerUi.Text(item.Name,16,true));card.Add(PlayerUi.Text(item.Id.StartsWith("steam:")?(Directory.Exists(item.InstallDirectory)?"Установлена · Steam":"Папка игры недоступна"):"Добавлена вручную",9,false,Theme.Muted));card.Add(PlayerUi.Text("Профиль: "+OptimizationOrchestrator.ProfileName(item.Profile),10));card.Add(PlayerUi.Text(item.Automatic?"Автоматическое применение включено":"Применение по вашей кнопке",9,false,Theme.Muted));if(!String.IsNullOrEmpty(item.LastResult))card.Add(PlayerUi.Text("Последний результат: "+item.LastResult,9,false,Theme.Muted));var choose=PlayerUi.Button(Context.Selected==item?"Выбрана":"Выбрать игру","selectGame_"+item.Id,Context.Selected==item);choose.Click+=delegate{Context.Select(item);};card.Add(choose);games.Controls.Add(card);}
  }
 }
 public sealed class OptimizationPage:PlayerPage {
  readonly Label systemState,cpuState,internetState,gpuState,shaderState;readonly CheckBox monitoring=new CheckBox {Text="Измерять CPU и память игры",AutoSize=true};readonly CheckBox automatic=new CheckBox {Text="Включать профиль при запуске выбранной игры",AutoSize=true};readonly ComboBox vendor=PlayerUi.Choice("NVIDIA","AMD"),gpuProfile=PlayerUi.Choice("Стандартный","Минимальная задержка","Максимальная плавность","Пользовательский");readonly NumericUpDown fps=new ThemedNumericUpDown {Minimum=20,Maximum=1000,Value=141,Width=100};bool render;
  public OptimizationPage(PlayerContext context,Action<int,string> expert,Action<string> navigate):base(context,"Оптимизация","Включайте только нужные возможности. У каждого изменения свой способ восстановления."){Name="optimizationPage";var grid=new CardGrid();
   var system=new PlayerCard();system.Add(PlayerUi.Text("Система",18,true));system.Add(PlayerUi.Text("Игровой режим Windows и выбранные параметры питания.",10,false,Theme.Muted));systemState=PlayerUi.Text("Не применено",10);system.Add(systemState);system.Add(automatic);automatic.CheckedChanged+=delegate{if(render)return;try{if(automatic.Checked&&!PlayerUi.Confirm(this,"Автоматический профиль",OptimizationOrchestrator.Summary(OptimizationOrchestrator.Options(context.Profile),new string[0])+"\n\nПрименять этот профиль при текущем или следующем запуске выбранной игры и восстанавливать после её завершения?",context.Preview)){render=true;automatic.Checked=false;render=false;return;}context.SetAutomatic(automatic.Checked);}catch(Exception error){context.Notice=error.Message;render=true;automatic.Checked=false;render=false;context.Emit();}};var systemDetails=PlayerUi.Button("Настроить профиль");systemDetails.Click+=delegate{expert(0,"Система · дополнительные параметры");};system.Add(systemDetails);var restore=PlayerUi.Button("Восстановить Windows");PlayerUi.Action(restore,async()=>{context.Session.SuppressCurrentRun(context.Selected,context.Processes);await context.Optimizer.Restore();},context);system.Add(restore);grid.Controls.Add(system);
   var cpu=new PlayerCard();cpu.Add(PlayerUi.Text("Процессор и память",18,true));cpu.Add(PlayerUi.Text("Следите за нагрузкой CPU и памятью игры. Автоматического ограничения фоновых программ здесь нет.",10,false,Theme.Muted));cpuState=PlayerUi.Text("Мониторинг выключен");cpu.Add(cpuState);cpu.Add(monitoring);monitoring.CheckedChanged+=async delegate{if(!render)await context.SetMonitoring(monitoring.Checked);};var cpuDetails=PlayerUi.Button("Подробнее и измерения");cpuDetails.Click+=delegate{expert(7,"Измерения CPU и памяти");};cpu.Add(cpuDetails);grid.Controls.Add(cpu);
   var internet=new PlayerCard();internet.Add(PlayerUi.Text("Интернет",18,true));internet.Add(PlayerUi.Text("Проверьте стабильность соединения и ограничьте исходящие фоновые загрузки выбранных программ.",10,false,Theme.Muted));internetState=PlayerUi.Text("Без измерений");internet.Add(internetState);var test=PlayerUi.Button("Проверить сеть");test.Click+=delegate{navigate("Internet");};internet.Add(test);var limit=PlayerUi.Button("Ограничить фоновые загрузки");limit.Click+=delegate{navigate("Internet");};internet.Add(limit);var reset=PlayerUi.Button("Восстановить ограничения");PlayerUi.Action(reset,async()=>{if(!context.Preview&&PlayerUi.Confirm(this,"Восстановить интернет","Удалить подтверждённые ограничения исходящей скорости, созданные OpenAntiLag? Потребуется UAC.",false)){var module=context.Recovery()[3];await context.Optimizer.Module(module.Name,module.Restore,()=>!module.Pending());}},context);internet.Add(reset);internet.Add(PlayerUi.Text("Ограничение затронет все экземпляры выбранного EXE. Маршруты игровых серверов не меняются.",9,false,Theme.Muted));grid.Controls.Add(internet);
   var gpu=new PlayerCard();gpu.Add(PlayerUi.Text("Видеокарта",18,true));gpu.Add(PlayerUi.Text("Игровые настройки поддерживаемых NVIDIA или AMD. Они глобальные и могут затронуть другие приложения.",10,false,Theme.Muted));gpuState=PlayerUi.Text("");gpu.Add(gpuState);gpu.Add(vendor);gpu.Add(gpuProfile);gpu.Add(PlayerUi.Text("Для плавности NVIDIA: лимит FPS ниже частоты монитора. G-SYNC/FreeSync должны быть настроены вами.",9,false,Theme.Muted));gpu.Add(fps);fps.Visible=false;gpuProfile.SelectedIndexChanged+=delegate{fps.Visible=gpuProfile.SelectedIndex==2&&vendor.SelectedIndex==0;};vendor.SelectedIndexChanged+=delegate{fps.Visible=gpuProfile.SelectedIndex==2&&vendor.SelectedIndex==0;};var gpuApply=PlayerUi.Button("Применить к видеокарте");PlayerUi.Action(gpuApply,async()=>{if(gpuProfile.SelectedIndex==3){expert(vendor.SelectedIndex==0?1:2,"Видеокарта · пользовательские параметры");return;}if(!PlayerUi.Confirm(this,"Глобальные настройки видеокарты","Профиль «"+gpuProfile.Text+"» для "+vendor.Text+".\nСтандартный восстанавливает исходные значения. Остальные меняют глобальные параметры драйвера; закройте игры. Reflex автоматически не включается. Для режима плавности нужен настроенный VRR; NVIDIA FPS="+fps.Value+".\n\nПродолжить?",context.Preview))return;await context.ApplyGpu(vendor.SelectedIndex==1,gpuProfile.Text,(int)fps.Value);},context);gpu.Add(gpuApply);var gpuDetails=PlayerUi.Button("Подробнее / восстановить");gpuDetails.Click+=delegate{expert(vendor.SelectedIndex==0?1:2,"Видеокарта · подробности и восстановление");};gpu.Add(gpuDetails);grid.Controls.Add(gpu);
   var shaders=new PlayerCard();shaders.Add(PlayerUi.Text("Шейдеры",18,true));shaders.Add(PlayerUi.Text("Подготовка поддерживаемых игр перед запуском может уменьшить подёргивания. Модуль загружается отдельно.",10,false,Theme.Muted));shaderState=PlayerUi.Text("Подготовка запускается только вами");shaders.Add(shaderState);var openShaders=PlayerUi.Button("Подготовить шейдеры");openShaders.Click+=delegate{expert(3,"Подготовка шейдеров");};shaders.Add(openShaders);shaders.Add(PlayerUi.Text("CS2 в используемом SCSKiller не поддерживается. Рекордер и внедрение DLL отключены. Подготовленный кэш этим экраном не удаляется.",9,false,Theme.Muted));grid.Controls.Add(shaders);Add(grid);
  }
  public override void RefreshState(){render=true;try{systemState.Text=Context.Optimizer.Status.HasProfile?"Есть применённый или ожидающий восстановления профиль":"Основной профиль выключен";automatic.Enabled=!Context.Optimizer.Status.Busy;automatic.Checked=Context.Selected!=null&&Context.Selected.Automatic&&!Context.LibraryReadOnly;monitoring.Checked=Context.Preferences.LocalMonitoring;cpuState.Text=Context.Measurements.Message;internetState.Text=Context.NetworkStatus();gpuState.Text=Context.GpuStatus()+(Context.Session.Faceit?"\nFACEIT обнаружен: простое применение глобальных параметров отключено.":"");shaderState.Text=Context.Selected!=null&&Context.Selected.Id=="steam:730"?"Для выбранной CS2 подготовка недоступна":"Подготовка запускается отдельно по кнопке";}finally{render=false;}}
 }
}
